'use strict';
const $ = id => document.getElementById(id);
const SAVE_KEY = 'woojin-game-v1', MAX = 1e300, OFFLINE_CAP = 8 * 3600;
const items = [
  {icon:'🍪',name:'바삭 쿠키',desc:'터치 +1원',base:20,type:'click',power:1},
  {icon:'🍔',name:'든든 버거',desc:'터치 +2원',base:70,type:'click',power:2},
  {icon:'🧋',name:'달콤한 버블티',desc:'초당 +1원',base:75,type:'auto',power:1},
  {icon:'🍕',name:'피자 파티',desc:'초당 +2원',base:270,type:'auto',power:2}
];
const achievements = [
  {id:'tap100',name:'손가락 준비 운동',detail:'100번 터치',title:'톡톡 탐험가',reward:150,test:s=>s.taps>=100,progress:s=>Math.min(100,s.taps)+'/100'},
  {id:'tap1000',name:'멈출 수 없는 손',detail:'1,000번 터치',title:'연타의 달인',reward:3000,test:s=>s.taps>=1000,progress:s=>Math.min(1000,s.taps)+'/1,000'},
  {id:'buy10',name:'간식 단골',detail:'업그레이드 10회 구매',title:'간식 단골',reward:300,test:s=>s.counts.reduce((a,b)=>a+b,0)>=10,progress:s=>Math.min(10,s.counts.reduce((a,b)=>a+b,0))+'/10'},
  {id:'level5',name:'성장하는 우진',detail:'레벨 5 달성',title:'든든한 친구',reward:800,test:s=>level(s)>=5,progress:s=>'LV. '+level(s)+'/5'},
  {id:'fever5',name:'피버의 주인공',detail:'피버 타임 5회 시작',title:'피버 마스터',reward:1800,test:s=>s.fevers>=5,progress:s=>Math.min(5,s.fevers)+'/5'}
];
const oldThresholds=[0,40,160,450,1100,2500,5500,12000,26000,55000,115000,240000];
const fresh=()=>({version:2,points:0,total:0,counts:[0,0,0,0],sound:true,taps:0,fevers:0,claimed:[],title:'말랑말랑 새싹',selectedPhoto:0,autoPhoto:true,highestLevel:1,lastSaved:Date.now()});
const nonnegative=(v,fallback=0)=>Number.isFinite(v)&&v>=0?Math.min(v,MAX):fallback;
function load(){let raw;try{raw=JSON.parse(localStorage.getItem(SAVE_KEY))}catch{};if(!raw||typeof raw!=='object')return fresh();const s=fresh();s.points=nonnegative(raw.points);s.total=Math.max(s.points,nonnegative(raw.total));if(Array.isArray(raw.counts))s.counts=items.map((_,i)=>Math.floor(nonnegative(raw.counts[i])));s.sound=typeof raw.sound==='boolean'?raw.sound:true;s.taps=Math.floor(nonnegative(raw.taps));s.fevers=Math.floor(nonnegative(raw.fevers));s.claimed=Array.isArray(raw.claimed)?raw.claimed.filter(id=>achievements.some(a=>a.id===id)):[];s.title=typeof raw.title==='string'?raw.title:s.title;s.selectedPhoto=Math.min(2,Math.floor(nonnegative(raw.selectedPhoto)));s.autoPhoto=raw.autoPhoto!==false;s.lastSaved=nonnegative(raw.lastSaved,Date.now());let previous=1;if(raw.version!==2){oldThresholds.forEach((t,i)=>{if(s.total>=t)previous=i+1})}s.highestLevel=Math.max(previous,Math.min(300,Math.floor(nonnegative(raw.highestLevel,1))));return s}
let state=load(), feverUntil=0, snackUntil=0, nextSnack=Date.now()+randomDelay(), audio, toastTimer, saveTimer, lastFrame=performance.now(), bounceEnergy=0, lastDraw='', lastFeverSeconds=-1;
function randomDelay(){return 150000+Math.random()*90000}
function threshold(l){return Math.min(MAX,80*Math.pow(2.2,l-1))}
function level(s=state){let l=Math.max(1,s.highestLevel||1);while(l<300&&s.total>=threshold(l))l++;return l}
function nextThreshold(l){return threshold(l)}
function format(n){if(!Number.isFinite(n))return '∞';n=Math.max(0,Math.floor(n));if(n<10000)return String(n);const units=['','만','억','조','경','해','자','양','구','간','정','재','극'];let group=Math.floor(Math.log10(n)/4);if(group>=units.length)return Math.floor(n/1e48)+'극';const lead=Math.floor(n/Math.pow(10000,group));let text=lead+units[group];if(group>1){const second=Math.floor(n/Math.pow(10000,group-1))%10000;if(second){const spoken=String(second).replace(/0+$/,'');const zeros=String(second).length-spoken.length;const suffix=zeros===3?'천':zeros===2?'백':zeros===1?'십':'';text+=' '+spoken+suffix+units[group-1]}}return text}
const plus=(a,b)=>Math.min(MAX,a+b);
function power(type){return items.reduce((sum,x,i)=>plus(sum,x.type===type?Math.min(MAX,x.power*state.counts[i]):0),type==='click'?1:0)}
function cost(i){return Math.min(MAX,Math.ceil(items[i].base*Math.pow(1.65,state.counts[i])))}
function save(){if(!saveTimer)saveTimer=setTimeout(()=>{saveTimer=null;saveNow()},250)}
function saveNow(){state.lastSaved=Date.now();try{localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch{toast('기록을 저장하지 못했어. 브라우저 저장 공간을 확인해줘.')}}
window.addEventListener('pagehide',saveNow);
let awayAt=state.lastSaved;
function applyAway(){const elapsed=Math.min(OFFLINE_CAP,Math.max(0,(Date.now()-awayAt)/1000));if(elapsed>2&&power('auto')>0){const amount=Math.min(MAX,power('auto')*elapsed);gain(amount,false);toast('자리 비운 동안 +'+format(amount)+'원 획득!')}awayAt=Date.now()}
document.addEventListener('visibilitychange',()=>{if(document.hidden){awayAt=Date.now();saveNow()}else{applyAway();tick=Date.now();lastFrame=performance.now()}});
function toast(message){const e=$('toast');e.textContent=message;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2800)}
const photo=new Image();photo.onload=()=>{$('photoError').classList.add('hidden');drawPhoto(true)};photo.onerror=()=>$('photoError').classList.remove('hidden');function loadPhoto(){photo.src='photos.png?retry='+Date.now()}$('retryPhoto').onclick=loadPhoto;loadPhoto();
let visualGrowth=0;
function growthTarget(){return Math.min(.30,.012*(level()-1)+.20*(1-Math.exp(-state.taps/300)))}
function drawPhoto(force=false){if(!photo.complete||!photo.naturalWidth)return;const l=level();if(state.autoPhoto)state.selectedPhoto=(l-1)%3;const key=state.selectedPhoto+':'+visualGrowth.toFixed(4);if(!force&&lastDraw===key)return;lastDraw=key;const c=$('photo'),ctx=c.getContext('2d'),sw=photo.width/3,sh=photo.height,w=c.width,h=c.height,sx=sw*state.selectedPhoto;ctx.clearRect(0,0,w,h);for(let y=0;y<h;y+=4){const t=Math.max(0,Math.min(1,(y/h-.30)/.45)),smooth=t*t*(3-2*t),spread=visualGrowth*smooth;const edge=w*.24,outer=edge*(1-spread),middle=w-2*outer;ctx.drawImage(photo,sx,sh*y/h,sw*.24,sh*4/h,0,y,outer,4);ctx.drawImage(photo,sx+sw*.24,sh*y/h,sw*.52,sh*4/h,outer,y,middle,4);ctx.drawImage(photo,sx+sw*.76,sh*y/h,sw*.24,sh*4/h,outer+middle,y,outer,4)}$('growthHint').textContent='몸집 성장 '+Math.round(visualGrowth*100)+'% · 터치할수록 쑥쑥!'}
function beep(){if(!state.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.frequency.setValueAtTime(520,audio.currentTime);o.frequency.exponentialRampToValueAtTime(290,audio.currentTime+.065);g.gain.setValueAtTime(.025,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.08);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.08)}catch{}}
function celebrate(){const scene=$('scene'),b=document.createElement('div');b.className='levelburst';b.innerHTML='<strong>LEVEL UP!</strong><small>LV. '+level()+' · 우진이가 성장했어!</small>';scene.append(b);setTimeout(()=>b.remove(),1800);if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<24;i++){const p=document.createElement('i');p.className='confetti';p.style.setProperty('--color',['#ffce55','#ff8156','#fff7db','#89bc89'][i%4]);p.style.setProperty('--x',(Math.random()-.5)*550+'px');p.style.setProperty('--y',(Math.random()-.5)*650+'px');scene.append(p);setTimeout(()=>p.remove(),1400)}}
function gain(n,animate=true){const old=level();state.points=plus(state.points,n);state.total=plus(state.total,n);const current=level();if(current>old){state.highestLevel=current;if(animate)celebrate()}render();save()}
function tap(x,y){const amount=power('click')*(Date.now()<feverUntil?2:1);state.taps++;gain(amount);beep();bounceEnergy=Math.min(1,bounceEnergy+.38);const f=document.createElement('span'),r=$('scene').getBoundingClientRect();f.className='float';f.textContent='+'+format(amount)+'원';f.style.left=Math.max(8,Math.min(r.width-65,x-r.left))+'px';f.style.top=(y-r.top)+'px';$('scene').append(f);setTimeout(()=>f.remove(),900)}
$('character').addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;e.preventDefault();tap(e.clientX,e.clientY)});$('character').addEventListener('click',e=>{if(e.detail===0){const r=$('character').getBoundingClientRect();tap(r.left+r.width/2,r.top+r.height*.6)}});$('character').addEventListener('contextmenu',e=>e.preventDefault());
$('upgrades').innerHTML=items.map((x,i)=>`<button class="upgrade" id="upgrade${i}" data-i="${i}"><span class="uicon">${x.icon}</span><span class="utext"><strong>${x.name}</strong><small>${x.desc}</small></span><span class="cost"></span></button>`).join('');
$('photoTabs').innerHTML=['운동하는 우진','파워 우진','장난꾸러기 우진'].map((n,i)=>`<button type="button" data-photo="${i}">${n}</button>`).join('');
$('achievements').innerHTML=achievements.map((a,i)=>`<div class="ach"><span aria-hidden="true">🏅</span><div class="info"><strong>${a.name}</strong><small id="achInfo${i}"></small></div><button type="button" id="achButton${i}" data-ach="${a.id}"></button></div>`).join('');
function render(){const l=level();if(state.autoPhoto)state.selectedPhoto=(l-1)%3;const prev=l===1?0:threshold(l-1),next=nextThreshold(l),cash=$('points');cash.textContent=format(state.points);$('level').textContent='LV. '+l;$('rank').textContent=state.title;$('clickstat').textContent='+'+format(power('click'))+'원';$('autostat').textContent=format(power('auto'))+'원 / 초';$('perclick').textContent='터치당 +'+format(power('click'))+'원 · 누적 '+format(state.total)+'원';$('next').textContent=l>=300?'최고 레벨 달성!':'다음 레벨까지';$('progressText').textContent=l>=300?'MAX LEVEL':format(Math.max(0,state.total-prev))+' / '+format(next-prev)+'원';$('fill').style.width=l>=300?'100%':Math.max(0,Math.min(100,(state.total-prev)/(next-prev)*100))+'%';$('sound').textContent=state.sound?'♪':'♩';$('sound').setAttribute('aria-pressed',String(state.sound));drawPhoto();$('photoTabs').querySelectorAll('button').forEach((b,i)=>{b.disabled=l<i+1;b.textContent=b.disabled?'🔒 LV.'+(i+1):['운동하는 우진','파워 우진','장난꾸러기 우진'][i];b.classList.toggle('selected',i===state.selectedPhoto);b.setAttribute('aria-pressed',String(i===state.selectedPhoto))});items.forEach((x,i)=>{const b=$('upgrade'+i);b.disabled=state.points<cost(i);b.querySelector('.cost').innerHTML='✦ '+format(cost(i))+'원<small>보유 '+state.counts[i].toLocaleString('ko-KR')+'</small>'});achievements.forEach((a,i)=>{const claimed=state.claimed.includes(a.id),done=a.test(state),b=$('achButton'+i);$('achInfo'+i).textContent=a.detail+' · '+a.progress(state)+' · 보상 '+format(a.reward)+'원';b.textContent=claimed?'완료':done?'받기':'진행 중';b.disabled=claimed||!done});const titles=['말랑말랑 새싹',...achievements.filter(a=>state.claimed.includes(a.id)).map(a=>a.title)];if(!titles.includes(state.title))state.title=titles[0];const select=$('titleSelect');if(select.dataset.options!==titles.join('|')){select.innerHTML=titles.map(t=>`<option value="${t}">${t}</option>`).join('');select.dataset.options=titles.join('|')}select.value=state.title;$('autoRate').textContent='초당 +'+format(power('auto'))+'원';$('autoPhoto').setAttribute('aria-pressed',String(state.autoPhoto))}
$('upgrades').onclick=e=>{const b=e.target.closest('button');if(!b)return;const i=+b.dataset.i,c=cost(i);if(state.points<c)return;state.points-=c;state.counts[i]++;beep();render();save()};
$('autoPhoto').onclick=()=>{state.autoPhoto=true;render();save();toast('레벨에 맞춰 사진이 자동으로 바뀌어!')};
$('photoTabs').onclick=e=>{const b=e.target.closest('button');if(!b||b.disabled)return;state.selectedPhoto=+b.dataset.photo;state.autoPhoto=false;render();save()};
$('achievements').onclick=e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const a=achievements.find(x=>x.id===b.dataset.ach);if(!a||!a.test(state)||state.claimed.includes(a.id))return;state.claimed.push(a.id);state.title=a.title;gain(a.reward);toast('칭호 획득: '+a.title)};
$('titleSelect').onchange=e=>{state.title=e.target.value;render();save()};
$('sound').onclick=()=>{state.sound=!state.sound;render();save()};
$('reset').onclick=()=>{if(confirm('모든 보유 금액과 업그레이드, 도전과제를 초기화할까?')){state=fresh();feverUntil=0;snackUntil=0;visualGrowth=0;document.body.classList.remove('fever-active');nextSnack=Date.now()+randomDelay();lastDraw='';render();save();toast('새로운 모험을 시작해!')}};
$('feverSnack').onclick=()=>{if(Date.now()>snackUntil)return;snackUntil=0;feverUntil=Date.now()+10000;nextSnack=feverUntil+randomDelay();document.body.classList.add('fever-active');state.fevers++;$('feverSnack').classList.add('hidden');beep();toast('피버 타임! 10초 동안 터치 수익 2배!');render();save()};
$('shareCard').onclick=async()=>{try{const c=document.createElement('canvas');c.width=900;c.height=1100;const x=c.getContext('2d');x.fillStyle='#f6efdf';x.fillRect(0,0,c.width,c.height);x.fillStyle='#5b3e2a';x.font='bold 46px sans-serif';x.fillText('우진이 키우기',60,95);x.drawImage($('photo'),150,140,600,800);x.fillStyle='#fffaf0';x.fillRect(150,800,600,230);x.fillStyle='#523a29';x.font='bold 44px sans-serif';x.fillText('LV. '+level()+'  ·  '+state.title,185,870);x.font='30px sans-serif';x.fillText('누적 '+format(state.total)+'원',185,930);x.font='22px sans-serif';x.fillText('woojin-belly-clicker.asnt1.chatgpt.site',185,990);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!blob)throw Error('이미지 생성 실패');const file=new File([blob],'woojin-record.png',{type:'image/png'});if(navigator.share&&navigator.canShare?.({files:[file]})){try{await navigator.share({title:'우진이 키우기',files:[file]});return}catch(e){if(e.name==='AbortError')return}}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('기록 카드를 저장했어!')}catch{toast('기록 카드를 만들지 못했어. 다시 시도해줘.')}};
function frame(now){const dt=Math.min(.05,(now-lastFrame)/1000);lastFrame=now;const target=growthTarget();if(Math.abs(target-visualGrowth)>.0001){visualGrowth+=(target-visualGrowth)*Math.min(1,dt*10);drawPhoto()}if(bounceEnergy>.001){bounceEnergy*=Math.exp(-10*dt);const motion=matchMedia('(prefers-reduced-motion: reduce)').matches?0:bounceEnergy;$('photo').style.transform=`translateY(${-5*motion}px) scale(${1+.018*motion},${1-.012*motion})`}else $('photo').style.transform='';requestAnimationFrame(frame)}requestAnimationFrame(frame);
let dripAmount=0,dripAt=Date.now();
function autoGain(amount){gain(amount,false);dripAmount+=amount;if(Date.now()-dripAt>=1000){const bubble=document.createElement('span');bubble.className='income-bubble';bubble.textContent='+'+format(dripAmount)+'원';$('incomeStream').append(bubble);setTimeout(()=>bubble.remove(),1500);dripAmount=0;dripAt=Date.now()}}
let tick=Date.now();setInterval(()=>{const now=Date.now(),dt=Math.max(0,(now-tick)/1000);tick=now;if(!document.hidden&&power('auto')>0)autoGain(Math.min(MAX,power('auto')*Math.min(dt,2)));if(!document.hidden&&now>=nextSnack&&!snackUntil&&now>=feverUntil){snackUntil=now+12000;nextSnack=now+randomDelay()+12000;$('feverSnack').classList.remove('hidden')}if(snackUntil&&now>=snackUntil){snackUntil=0;$('feverSnack').classList.add('hidden')}const seconds=Math.max(0,Math.ceil((feverUntil-now)/1000));if(seconds!==lastFeverSeconds){lastFeverSeconds=seconds;document.body.classList.toggle('fever-active',seconds>0);$('feverStatus').classList.toggle('hidden',seconds===0);$('feverStatus').textContent=seconds?'🔥 피버 타임 · 터치 2배 '+seconds+'초':''}},250);
render();
applyAway();
